CREATE TABLE "Meal" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"name" TEXT NOT NULL,"carbs" DOUBLE PRECISION,"calories" DOUBLE PRECISION,"protein" DOUBLE PRECISION,"photoUrl" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Meal_pkey" PRIMARY KEY ("id"));CREATE TABLE "Activity" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" TEXT NOT NULL,"minutes" INTEGER NOT NULL,"calories" DOUBLE PRECISION,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Activity_pkey" PRIMARY KEY ("id"));ALTER TABLE "Meal" ADD CONSTRAINT "Meal_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "Activity" ADD CONSTRAINT "Activity_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;CREATE INDEX "Meal_userId_createdAt_idx" ON "Meal"("userId","createdAt");CREATE INDEX "Activity_userId_createdAt_idx" ON "Activity"("userId","createdAt");